def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = {r for r, row in enumerate(grid) if len(set(row)) == 1}
    col_seps = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    def spans(n, separators):
        result, start = [], 0
        for i in sorted(separators):
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < n:
            result.append((start, n))
        return result

    rows, cols = spans(h, row_seps), spans(w, col_seps)
    panels = [(r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols]
    counts = {}
    for r0, r1, c0, c1 in panels:
        for r in range(r0, r1):
            for c in range(c0, c1):
                color = grid[r][c]
                counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    source = max(panels, key=lambda p: sum(
        grid[r][c] != background
        for r in range(p[0], p[1]) for c in range(p[2], p[3])
    ))
    r0, r1, c0, c1 = source
    ph, pw = r1-r0, c1-c0
    output = [row[:] for row in grid]
    for a, b, x, y in panels:
        for r in range(a, b):
            for c in range(x, y):
                output[r][c] = grid[r0+(r-a)%ph][c0+(c-x)%pw]
    return output

